import React, { useState } from "react";
import { TextField, Box, Typography } from "@mui/material";
import { ErrorOutline } from "@mui/icons-material";
import india from "../Assets/india.png"

const BasicInput = ({ labelName, fieldName, value, onChange, placeholder, type, error, helperText }) => {
  const [phoneError, setPhoneError] = useState("");
  const [touched, setTouched] = useState(false);

  // Indian flag emoji
  const indianFlag = "🇮🇳";
  
  // Phone number validation function
  const validatePhoneNumber = (phone) => {
    if (!phone) return "Phone number is required";
    if (phone.length !== 13) return "Phone number must be 10 digits";
    if (!phone.startsWith('+91')) return "Phone number must start with +91";
    
    const digits = phone.substring(3);
    if (!/^\d{10}$/.test(digits)) return "Invalid phone number format";
    if (!/^[6-9]/.test(digits)) return "Phone number must start with 6-9";
    
    return "";
  };

  // Handle phone number input
  const handlePhoneChange = (e) => {
    let inputValue = e.target.value;
    
    // Remove non-digit characters except +
    inputValue = inputValue.replace(/[^\d+]/g, '');
    
    // Ensure it starts with +91
    if (!inputValue.startsWith('+91')) {
      inputValue = '+91' + inputValue.replace(/^\+91/, '');
    }
    
    // Limit to 13 characters (+91 + 10 digits)
    if (inputValue.length > 13) {
      inputValue = inputValue.slice(0, 13);
    }
    
    // Validate only if user has started typing
    if (touched || inputValue.length > 3) {
      const validationError = validatePhoneNumber(inputValue);
      setPhoneError(validationError);
    }
    
    // Create synthetic event to pass to parent's onChange
    const syntheticEvent = {
      target: {
        name: fieldName,
        value: inputValue
      }
    };
    
    onChange(syntheticEvent);
  };

  const handleBlur = () => {
    setTouched(true);
    if (isPhoneNumber) {
      const validationError = validatePhoneNumber(value);
      setPhoneError(validationError);
    }
  };

  const handleFocus = () => {
    setTouched(true);
  };

  // Check if it's a phone number field
  const isPhoneNumber = type === 'number' && fieldName?.toLowerCase().includes('phone');

  // Combine errors (parent error + phone validation error)
  const hasError = error || (isPhoneNumber && phoneError && touched);
  const displayHelperText = helperText || (isPhoneNumber && touched ? phoneError : '');

  return (
    <div>
      <div className="w-full my-2">
        <label className="text-white block mb-2">
          {labelName}
          {/* {isPhoneNumber && (
            <span className="text-gray-400 text-sm ml-2">(10 digits starting with 6-9)</span>
          )} */}
        </label>
        <TextField
          id={`${fieldName}-input`}
          type={isPhoneNumber ? "tel" : type}
          placeholder={placeholder}
          value={value}
          onChange={isPhoneNumber ? handlePhoneChange : onChange}
          onBlur={handleBlur}
          onFocus={handleFocus}
          fullWidth
          multiline={type === 'multiline'}
          rows={type === 'multiline' ? 4 : 1}
          error={hasError}
          helperText={displayHelperText}
          InputProps={{
            startAdornment: isPhoneNumber ? (
              <Box sx={{ display: 'flex', alignItems: 'center', mr: 1 }}>
                <img style={{ fontSize: '18px', marginRight: '4px' }}>{india}</img>
                <span style={{ 
                  color: hasError ? '#f44336' : '#ffffff', 
                  fontWeight: '500',
                  opacity: hasError ? 0.7 : 1
                }}>+91</span>
              </Box>
            ) : null,
            endAdornment: hasError ? (
              <ErrorOutline sx={{ color: '#f44336', marginLeft: 1 }} />
            ) : null,
          }}
          sx={{
            "& .MuiOutlinedInput-root": {
              backgroundColor: "rgba(255, 255, 255, 0.1)",
              backdropFilter: "blur(10px)",
              borderRadius: "8px",
              alignItems: type === 'multiline' ? 'flex-start' : 'center',
              transition: "all 0.3s ease",

              "&:hover": {
                backgroundColor: hasError ? "rgba(244, 67, 54, 0.1)" : "rgba(255, 255, 255, 0.15)",
                "& .MuiOutlinedInput-notchedOutline": {
                  borderColor: hasError ? "#f44336" : "rgba(255, 255, 255, 0.5)",
                },
              },

              "&.Mui-focused": {
                backgroundColor: hasError ? "rgba(244, 67, 54, 0.1)" : "rgba(255, 255, 255, 0.2)",
                "& .MuiOutlinedInput-notchedOutline": {
                  borderColor: hasError ? "#f44336" : "#FF9800",
                  borderWidth: "2px",
                },
              },

              "&.Mui-error": {
                backgroundColor: "rgba(244, 67, 54, 0.1)",
                "& .MuiOutlinedInput-notchedOutline": {
                  borderColor: "#f44336",
                },
              },

              "& .MuiOutlinedInput-input": {
                color: hasError ? "#f44336" : "#ffffff",
                padding: type === 'multiline' ? "12px" : "10px 12px",
                
                "&::placeholder": {
                  color: hasError ? "rgba(244, 67, 54, 0.9)" : "rgba(255, 255, 255, 0.7)",
                },
              },
            },

            "& .MuiOutlinedInput-notchedOutline": {
              borderColor: hasError ? "#f44336" : "rgba(255, 255, 255, 0.3)",
              transition: "all 0.3s ease",
            },

            "& .MuiFormHelperText-root": {
              color: hasError ? "#f44336" : "rgba(255, 255, 255, 0.7)",
              marginLeft: 0,
              fontSize: "0.75rem",
            },
            
            // Style for multiline textarea
            "& .MuiOutlinedInput-inputMultiline": {
              resize: "vertical",
              minHeight: type === 'multiline' ? "80px" : "auto",
            },
          }}
        />
      </div>
    </div>
  );
};

export default BasicInput;
